#ifndef ROHR_EDITOR_STARTER_MAIN_H
#define ROHR_EDITOR_STARTER_MAIN_H

static const char editor_starter_main_source[] =
    "/* Generated by Rohr Engine. This file is developer-owned after creation.\n"
    " * You may use, modify, and distribute it without restriction. */\n"
    "#include \"project_viewports.h\"\n"
    "\n"
    "#include <stdio.h>\n"
    "\n"
    "typedef struct Tutorial {\n"
    "    ProjectObjects authored;\n"
    "    Entity platform;\n"
    "    Entity box;\n"
    "    Entity particle;\n"
    "    Entity soft_body;\n"
    "} Tutorial;\n"
    "\n"
    "static bool ok(EngineResult result) {\n"
    "    if(!rohr_error_check(result)) return true;\n"
    "    fprintf(stderr, \"error %d: %s\\n\", (int)result.result.error,\n"
    "        rohr_error_message_get(result));\n"
    "    return false;\n"
    "}\n"
    "\n"
    "/* Only unwrap the result; all construction stays in main below. */\n"
    "static bool take(EntityResult added, Entity *output) {\n"
    "    if(rohr_error_check(added))\n"
    "        return ok(rohr_error_result_error(added.result.error));\n"
    "    *output = added.result.value;\n"
    "    return true;\n"
    "}\n"
    "\n"
    "/* Cameras call this each frame. Drawing does not create or configure entities. */\n"
    "static void draw_tutorial(CameraId camera, void *context) {\n"
    "    const Tutorial *scene = context;\n"
    "    (void)camera;\n"
    "    rohr_graphics_layer_active_set(-100);\n"
    "    rohr_graphics_background_draw((Color){18, 22, 30, 255});\n"
    "    rohr_graphics_layer_active_set(0);\n"
    "    project_objects_draw_all(&scene->authored);\n"
    "    rohr_graphics_hit_box_colored_draw(scene->platform, GRAPHICS_FILLED,\n"
    "        (Color){95, 115, 140, 255});\n"
    "    rohr_graphics_hit_box_colored_draw(scene->box, GRAPHICS_FILLED,\n"
    "        (Color){245, 140, 70, 255});\n"
    "    rohr_graphics_particle_draw(scene->particle, GRAPHICS_FILLED);\n"
    "    (void)rohr_graphics_soft_body_draw(scene->soft_body,\n"
    "        (Color){65, 175, 145, 180}, (Color){110, 235, 195, 255},\n"
    "        (Color){230, 245, 240, 255});\n"
    "}\n"
    "\n"
    "int main(void) {\n"
    "    Tutorial scene = {0};\n"
    "    ProjectViewports viewports = {0};\n"
    "    int exit_code = 1;\n"
    "    if(!ok(rohr_directory_working_set(rohr_directory_base_get()))) return 1;\n"
    "    if(!ok(rohr_engine_start()) || !ok(rohr_graphics_start())) goto done;\n"
    "\n"
    "    /* 1. Spawn complete editor-authored objects in one call each.\n"
    "     * Bodies, visuals, anchors, and internal joints are already connected.\n"
    "     * The position is an offset for the entire independent instance. */\n"
    "    if(!ok(project_settings_apply()) ||\n"
    "            !ok(project_controllers_create(&scene.authored.controllers)) ||\n"
    "            !ok(starter_create(&scene.authored.starter, (Position){0, 0})) ||\n"
    "            !ok(tug_create(&scene.authored.tug, (Position){0, 0}))) goto done;\n"
    "    scene.authored.created = true;\n"
    "    if(!ok(project_viewports_create(&viewports, &scene.authored))) goto done;\n"
    "\n"
    "    /* 2. Build additional entities directly, without editor definitions.\n"
    "     * These appear only when running this application, not in Simulate Scene.\n"
    "     * Rigid bodies are entities with geometry and explicit physics properties. */\n"
    "    if(!take(rohr_entity_add(), &scene.platform) ||\n"
    "            !ok(rohr_physics_position_set(scene.platform, (Position){430, -200})) ||\n"
    "            !ok(rohr_physics_hitbox_set(scene.platform, rohr_math_square_create(220, 40))) ||\n"
    "            !ok(rohr_entity_components_add(scene.platform, ROHR_COLLISION)) ||\n"
    "            !ok(rohr_physics_static_set(scene.platform)) ||\n"
    "            !ok(rohr_physics_friction_set(scene.platform, 0.5f))) goto done;\n"
    "\n"
    "    if(!take(rohr_entity_add(), &scene.box) ||\n"
    "            !ok(rohr_physics_position_set(scene.box, (Position){375, 0})) ||\n"
    "            !ok(rohr_physics_hitbox_set(scene.box, rohr_math_square_create(40, 40))) ||\n"
    "            !ok(rohr_entity_components_add(scene.box, ROHR_COLLISION)) ||\n"
    "            !ok(rohr_physics_dynamic_set(scene.box)) ||\n"
    "            !ok(rohr_physics_mass_set(scene.box, 2.0f)) ||\n"
    "            !ok(rohr_physics_friction_set(scene.box, 0.5f)) ||\n"
    "            !ok(rohr_physics_gravity_enable(scene.box))) goto done;\n"
    "\n"
    "    /* Descriptions specify complete configuration; omitted fields are zero. */\n"
    "    if(!take(rohr_physics_particle_add((ParticleDescription){\n"
    "            .position = {430, 220}, .radius = 12, .mass_value = 1,\n"
    "            .friction = 0.5f, .restitution = 0.3f,\n"
    "            .collision_filter = {ROHR_COLLISION_CATEGORY_DEFAULT, ROHR_COLLISION_CATEGORY_ALL},\n"
    "            .gravity_enabled = true, .collision_enabled = true}),\n"
    "            &scene.particle)) goto done;\n"
    "\n"
    "    /* A soft body starts empty. Own its nodes, beams, and filled area so deleting\n"
    "     * the body later also deletes those children. Connections alone do not own. */\n"
    "    if(!take(rohr_physics_soft_body_add((SoftBodyDescription){\n"
    "            .position = {475, 100}}), &scene.soft_body)) goto done;\n"
    "    const Position corners[] = {{-35, -35}, {35, -35}, {35, 35}, {-35, 35}};\n"
    "    Entity nodes[4] = {0};\n"
    "    for(size_t i = 0; i < 4; ++i) {\n"
    "        if(!take(rohr_physics_soft_body_node_local_add((SoftBodyNodeDescription){\n"
    "                .owner = scene.soft_body, .position = corners[i],\n"
    "                .mass = 1, .radius = 6, .friction = 0.5f,\n"
    "                .collision_filter = {ROHR_COLLISION_CATEGORY_SOFT_BODY_NODE,\n"
    "                    ROHR_COLLISION_CATEGORY_ALL},\n"
    "                .gravity_enabled = true, .collision_enabled = true}), &nodes[i])) goto done;\n"
    "    }\n"
    "    /* Four boundary beams and two diagonals keep the square together.\n"
    "     * Rest lengths are measured from the nodes; beam collision defaults off. */\n"
    "    const size_t endpoints[][2] = {{0, 1}, {1, 2}, {2, 3}, {3, 0}, {0, 2}, {1, 3}};\n"
    "    for(size_t i = 0; i < 6; ++i) {\n"
    "        Entity beam;\n"
    "        if(!take(rohr_physics_soft_body_beam_add((SoftBodyBeamDescription){\n"
    "                .owner = scene.soft_body,\n"
    "                .node_a = nodes[endpoints[i][0]], .node_b = nodes[endpoints[i][1]],\n"
    "                .stiffness = 800, .damping = 15}), &beam)) goto done;\n"
    "    }\n"
    "    Entity area;\n"
    "    if(!take(rohr_physics_soft_body_area_add((SoftBodyAreaDescription){\n"
    "            .owner = scene.soft_body,\n"
    "            .geometry.outer = {.nodes = {nodes[0], nodes[1], nodes[2], nodes[3]},\n"
    "                .node_count = 4}, .visible = true}), &area)) goto done;\n"
    "\n"
    "    /* Keep the authored viewport and UI, but draw both construction examples. */\n"
    "    if(!ok(rohr_camera_render_callback_set(scene.authored.starter.camera_main_camera,\n"
    "            draw_tutorial, &scene))) goto done;\n"
    "\n"
    "    while(true) {\n"
    "        SDL_Event event;\n"
    "        rohr_input_frame_begin();\n"
    "        while((event = rohr_engine_event_poll()).type != 0) {\n"
    "            if(event.type == SDL_EVENT_QUIT) { exit_code = 0; goto done; }\n"
    "        }\n"
    "        if(rohr_input_key_pressed_check(SDL_SCANCODE_ESCAPE)) break;\n"
    "        if(rohr_engine_update().header.status == ROHR_REPORT_FAILED) goto done;\n"
    "        if(rohr_physics_update(rohr_engine_tick_delta_get()).header.status == ROHR_REPORT_FAILED) goto done;\n"
    "        rohr_graphics_sprite_frames_update(rohr_engine_tick_get(), rohr_engine_time_get());\n"
    "        rohr_graphics_show();\n"
    "    }\n"
    "    exit_code = 0;\n"
    "done:\n"
    "    if(exit_code != 0) fprintf(stderr, \"Game initialization or update failed\\n\");\n"
    "    /* Destroy viewports before their callback context and camera owners. */\n"
    "    project_viewports_destroy(&viewports);\n"
    "    if(rohr_entity_alive_check(scene.soft_body)) (void)rohr_entity_delete(scene.soft_body);\n"
    "    if(rohr_entity_alive_check(scene.particle)) (void)rohr_entity_delete(scene.particle);\n"
    "    if(rohr_entity_alive_check(scene.box)) (void)rohr_entity_delete(scene.box);\n"
    "    if(rohr_entity_alive_check(scene.platform)) (void)rohr_entity_delete(scene.platform);\n"
    "    project_objects_destroy_all(&scene.authored);\n"
    "    rohr_graphics_stop();\n"
    "    rohr_engine_stop();\n"
    "    return exit_code;\n"
    "}\n"
;

#endif
